import { MakeLogicType, actions, kea, listeners, path } from 'kea'
import posthog from 'posthog-js'

import type { TodayRailPane } from '~/layout/today/todayShellLogic'

export type TodayRailCardSection = 'recents' | 'pinned'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRailCardLogicActions {
    cardShown: (
        pane: TodayRailPane,
        recentCount: number,
        pinnedCount: number
    ) => {
        pane: TodayRailPane
        pinnedCount: number
        recentCount: number
    }
    itemOpened: (
        pane: TodayRailPane,
        section: TodayRailCardSection,
        position: number,
        newTab: boolean
    ) => {
        newTab: boolean
        pane: TodayRailPane
        position: number
        section: TodayRailCardSection
    }
}

export type todayRailCardLogicType = MakeLogicType<{}, todayRailCardLogicActions>

export const todayRailCardLogic = kea<todayRailCardLogicType>([
    path(['products', 'today', 'frontend', 'rail', 'todayRailCardLogic']),
    actions({
        cardShown: (pane: TodayRailPane, recentCount: number, pinnedCount: number) => ({
            pane,
            recentCount,
            pinnedCount,
        }),
        itemOpened: (pane: TodayRailPane, section: TodayRailCardSection, position: number, newTab: boolean) => ({
            pane,
            section,
            position,
            newTab,
        }),
    }),
    listeners({
        cardShown: ({ pane, recentCount, pinnedCount }) => {
            posthog.capture('today rail card shown', { pane, recent_count: recentCount, pinned_count: pinnedCount })
        },
        itemOpened: ({ pane, section, position, newTab }) => {
            posthog.capture('today rail card item opened', { pane, section, position, new_tab: newTab })
        },
    }),
])
